"use client"

/**
 * Bandeja de conversaciones.
 * Fuente: concepto visual de Divan Raj (@desdivj),
 * https://x.com/desdivj/status/2119738295039250507
 * Licencia: sin licencia, clean-room. No se copiaron assets, logos,
 * ilustraciones ni textos.
 */

import { cn } from "@/lib/utils"
import { deskInitials } from "@/lib/inbox"
import { presenceDotStyle, type ConversationItemData } from "@/lib/thread-desk"

export type ConversationItemProps = {
  item: ConversationItemData
  selected?: boolean
  id?: string
  onSelect?: (id: string) => void
  status?: "ready" | "loading" | "empty" | "error"
  emptyLabel?: string
  loadingLabel?: string
  error?: string
  className?: string
}

export function ConversationItem({
  item,
  selected = false,
  id,
  onSelect,
  status = "ready",
  emptyLabel = "Sin conversación",
  loadingLabel = "Cargando la fila",
  error,
  className,
}: ConversationItemProps) {
  if (status === "loading") return <div role="status" aria-label={loadingLabel} className="h-14 animate-pulse rounded-xl bg-muted" />
  if (status === "error") return <p role="alert" className="text-sm text-destructive">{error}</p>
  if (status === "empty") return <p role="status" className="text-sm text-muted-foreground">{emptyLabel}</p>
  const contact = item.kind === "contact"
  return (
    <button
      id={id}
      type="button"
      role="option"
      aria-selected={selected}
      data-slot="conversation-item"
      className={cn(
        "flex min-h-11 w-full items-center gap-3 rounded-xl px-2 py-2 text-left focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none",
        selected ? "bg-muted" : "hover:bg-muted/70",
        className,
      )}
      onClick={() => onSelect?.(item.id)}
    >
      <span className="relative grid size-10 shrink-0 place-items-center rounded-full bg-foreground text-xs font-medium text-background">
        <span aria-hidden>{deskInitials(item.title)}</span>
        {item.presence ? (
          <span
            data-presence={item.presence}
            className="absolute end-0 bottom-0 size-2.5 rounded-full ring-2 ring-background"
            style={presenceDotStyle(item.presence)}
          />
        ) : null}
      </span>
      <span className="min-w-0 flex-1">
        <span className="flex items-baseline gap-2">
          <span className={cn("truncate text-sm", item.unread ? "font-semibold" : "font-medium")}>{item.title}</span>
          {item.time ? <time className="ms-auto shrink-0 text-xs text-muted-foreground tabular-nums">{item.time}</time> : null}
        </span>
        {contact && item.role ? <span className="mt-0.5 block truncate text-xs text-muted-foreground">{item.role}</span> : null}
        {!contact && item.preview ? <span className="mt-0.5 block truncate text-xs text-muted-foreground">{item.preview}</span> : null}
        {item.channel || item.stage || item.windowLabel ? (
          <span className="mt-1 flex min-w-0 flex-wrap items-center gap-1.5">
            {item.channel ? <span className="text-xs font-medium text-primary">{item.channel}</span> : null}
            {item.stage ? <span className="rounded-full border border-border px-1.5 py-0.5 text-[11px] text-muted-foreground">{item.stage}</span> : null}
            {item.windowLabel ? <span className="text-[11px] font-medium text-primary">{item.windowLabel}</span> : null}
          </span>
        ) : null}
      </span>
      {item.unread ? (
        <span className="grid h-5 min-w-5 place-items-center rounded-full bg-primary px-1 text-[11px] font-medium text-primary-foreground tabular-nums">
          {item.unread}
        </span>
      ) : null}
    </button>
  )
}

/**
 * Bandeja de conversaciones.
 * Fuente: concepto visual de Divan Raj (@desdivj),
 * https://x.com/desdivj/status/2119738295039250507
 * Licencia: sin licencia, clean-room. No se copiaron assets, logos,
 * ilustraciones ni textos.
 * Tipos y puertos. Sin red, sin Supabase y sin dominio de un canal.
 */

import type { CSSProperties, ReactNode } from "react"

import { foldInboxText, type DeskPresence } from "@/lib/inbox"

/** Online uses the host success token, then chart-2. It is not the accent. */
export function presenceDotStyle(presence: DeskPresence): CSSProperties {
  if (presence === "online") return { backgroundColor: "var(--success, var(--chart-2))" }
  if (presence === "offline") return { backgroundColor: "var(--muted-foreground)" }
  return { backgroundColor: "var(--accent-foreground)" }
}

export type ThreadStatus = "ready" | "loading" | "empty" | "error" | "offline"

export type ThreadFilter = {
  value: string
  label: string
}

export type ConversationSection = {
  id: string
  label: string
  hint?: string
}

export type ConversationItemData = {
  id: string
  title: string
  preview?: string
  time?: string
  unread?: number
  section?: string
  tags?: readonly string[]
  presence?: DeskPresence
  role?: string
  kind?: "thread" | "contact"
  stage?: string
  windowLabel?: string
  channel?: ReactNode
}

export type DeliveryState = "sending" | "sent" | "delivered" | "read" | "failed"

export type ThreadNote = {
  title: string
  detail: string
  body?: string
}

export type ThreadFile = {
  name: string
  detail: string
  status?: string
}

export type ThreadInvoice = {
  title: string
  amount: string
  due: string
}

export type ThreadMetric = {
  title: string
  chip?: string
  value: string
  caption?: string
  filled: number
  total: number
  start: string
  end: string
}

export type ThreadMessageData = {
  id: string
  side: "incoming" | "outgoing"
  author: string
  time?: string
  body?: string
  delivery?: DeliveryState
  deliveryLabel?: string
  grouped?: "single" | "start" | "middle" | "end"
  enter?: boolean
  note?: ThreadNote
  file?: ThreadFile
  invoice?: ThreadInvoice
  metric?: ThreadMetric
}

export type SuggestionItem = {
  id: string
  label: string
}

export type SecretField = {
  id: string
  label: string
  masked: string
  revealed: string
}

export type PartyFact = {
  id: string
  label: string
  value: string
}

export type PartyMember = {
  id: string
  name: string
  role: string
}

export type PartyFile = {
  id: string
  name: string
  detail: string
}

export type PartyDeal = {
  title: string
  status: string
  amount: string
  value: number
  label: string
}

export type PartyPanelData = {
  name: string
  meta?: string
  deal?: PartyDeal
  facts?: readonly PartyFact[]
  members?: readonly PartyMember[]
  files?: readonly PartyFile[]
  secrets?: readonly SecretField[]
}

export function matchesConversation(item: ConversationItemData, filter: string | undefined, query: string) {
  if (filter && filter !== "all") {
    const tagged = item.tags?.includes(filter) || (filter === "unread" && (item.unread ?? 0) > 0)
    if (!tagged) return false
  }
  const needle = query.trim()
  if (!needle) return true
  const hay = [item.title, item.preview, item.role, item.stage, item.windowLabel].filter(Boolean).join(" ")
  return foldInboxText(hay).includes(foldInboxText(needle))
}

export function groupMessages(messages: readonly ThreadMessageData[]): ThreadMessageData[] {
  return messages.map((message, index) => {
    if (message.grouped) return message
    const prev = messages[index - 1]
    const next = messages[index + 1]
    const same = (other?: ThreadMessageData) =>
      Boolean(other && other.side === message.side && other.author === message.author && !other.file && !other.invoice && !other.metric && !message.file && !message.invoice && !message.metric)
    const before = same(prev)
    const after = same(next)
    const grouped = before && after ? "middle" : before ? "end" : after ? "start" : "single"
    return { ...message, grouped }
  })
}

/**
 * Shared types for the desk pieces. No fetching, no theme.
 * Dates are calendar days (`YYYY-MM-DD`). The host owns locale and timezone.
 */

export const DESK_PRESENCES = ["online", "offline", "away"] as const

export type DeskPresence = (typeof DESK_PRESENCES)[number]

export type DeskMessage = {
  id: string
  author: string
  body: string
  /** Preformatted time. */
  time: string
  side: "incoming" | "outgoing"
  note?: boolean
  receipt?: "seen" | "unseen"
}

export type DeskOption = {
  value: string
  label: string
}

const DATE_RE = /^(\d{4})-(\d{2})-(\d{2})$/

export function foldInboxText(value: string): string {
  return value.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase()
}

export function isCalendarDate(value: string | undefined): value is string {
  return Boolean(value && DATE_RE.test(value))
}

/** True when `due` is a calendar day before `today`. */
export function isOverdueDate(due: string | undefined, today: string): boolean {
  if (!isCalendarDate(due) || !isCalendarDate(today)) return false
  return due < today
}

export function formatDeskDate(iso: string, locale?: string): string {
  if (!isCalendarDate(iso)) return iso
  const [year, month, day] = iso.split("-").map(Number)
  return new Intl.DateTimeFormat(locale, { dateStyle: "medium", timeZone: "UTC" }).format(
    new Date(Date.UTC(year, month - 1, day)),
  )
}

export function deskInitials(name: string): string {
  const letters = name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase() ?? "")
    .join("")
  return letters || "?"
}
